#include <control/domain_controller.hpp>
namespace rebuntu::management { static std::string name(Domain d){switch(d){case Domain::process:return"process";case Domain::service:return"service";case Domain::storage:return"storage";case Domain::network:return"network";case Domain::gpu:return"gpu";case Domain::package:return"package";case Domain::configuration:return"configuration";case Domain::secrets:return"secrets";case Domain::identity:return"identity";case Domain::shell:return"shell";case Domain::terminal:return"terminal";case Domain::development:return"development";}return"unknown";} platform::v0040::ChangePlan DomainController::prepare(const Request&r)const{planning::ChangePlanner p;bool privileged=r.domain!=Domain::terminal&&r.domain!=Domain::development;return p.plan({name(r.domain),r.target,r.property,r.value,privileged,r.property=="remove"||r.property=="delete"});} void DomainController::observe(const Request&r,std::string source){state_.upsert({r.target,r.property,r.value,std::move(source),1.0});} }
